    r3.results[0].reasons.some((z) => z.kind === 'semantic' && z.label === 'Top 1% resume match for “x”'), { X, first: brief(r3)[0] });

  // 4
  const r4 = await searchCandidates({ ...E, countries: ['Canada'] } as any, { query: q() as any, relaxable: ['countries'], embedQuery: reject });
  ok('4', JSON.stringify(r4.relaxed) === JSON.stringify([{ field: 'countries', message: 'No candidates in Canada match, so country was ignored.' }]) && r4.filters.countries.length === 0 && r4.total === 1000, r4.relaxed);

  // 5
  const r5 = await searchCandidates({ ...E, countries: ['Canada'] } as any, { query: q() as any, relaxable: [], embedQuery: reject });
  ok('5', r5.total === 0 && r5.results.length === 0 && r5.relaxed.length === 0);

  // 6
  const r6 = await searchCandidates({ ...E, skills: ['Rust', 'Elixir'] } as any, { query: q() as any, relaxable: ['skills'], embedQuery: reject });
  const [{ n: rustN }] = await db.all<{ n: number }>(sql`SELECT count(*) AS n FROM candidate_skills WHERE skill = 'Rust'`);
  ok('6', JSON.stringify(r6.relaxed) === JSON.stringify([{ field: 'skills', message: 'No candidates have Elixir alongside the other requirements, so Elixir was ignored.' }]) &&
    JSON.stringify(r6.filters.skills) === '["Rust"]' && r6.total === rustN && r6.results.every((x) => JSON.stringify(x.matchedSkills) === '["Rust"]'), { relaxed: r6.relaxed, total: r6.total, rustN });

  // 7
  const r7 = await searchCandidates({ ...E, countries: ['Canada'], maxSalary: 1000 } as any, { query: q() as any, relaxable: ['countries', 'maxSalary'], embedQuery: reject });
  ok('7', JSON.stringify(r7.relaxed.map((z) => z.field)) === '["countries","maxSalary"]' && r7.relaxed[1].message === 'No candidates under $1,000/yr match, so the salary cap was ignored.', r7.relaxed);

  // 8
  const r8 = await searchCandidates({ ...E, skills: ['Python'] } as any, { query: q({ keywords: ['django'], searchText: 'python django' }) as any, embedQuery: async () => vx });
  const order = ['skill', 'keyword', 'semantic', 'experience'];
  const [{ n: pyN }] = await db.all<{ n: number }>(sql`SELECT count(*) AS n FROM candidate_skills WHERE skill = 'Python'`);
  ok('8', r8.results.every((x) => { const idx = x.reasons.map((z) => order.indexOf(z.kind)); return idx.every((v, i) => v >= 0 && (i === 0 || idx[i - 1] <= v)); }) &&
    r8.results.every((x, i, a) => i === 0 || a[i - 1].score >= x.score) && r8.results.length <= 10 && r8.total === pyN, { total: r8.total, pyN });
  console.log(brief(r8).join('\n'));

  // 9
  const qq = q({ searchText: 'Senior React' });
  const r9 = await searchCandidates(E as any, { query: qq as any, queryText: '  Senior React  ', embedQuery: reject });
  ok('9', r9.query === 'Senior React' && r9.interpretation === qq, r9.query);

  // 10
  const all = [r2, r3, r8].flatMap((r) => r.results.flatMap((x) => x.reasons.filter((z) => z.kind === 'semantic')));
  ok('10', all.length > 0 && all.every((z) => /^Top \d+% resume match for “.+”$/.test(z.label)), all.map((z) => z.label).slice(0, 12));
})();

