import 'dotenv/config';
import { searchCandidates } from '/home/rk/Projects/Dev/oremono/crew-interview-challenge-rishab-kohale/.claude/worktrees/agent-ac0da594b65bc5d89/src/lib/search/filter-search';
const E = { countries: [], skills: [], minYears: null, maxYears: null, minSalary: null, maxSalary: null };
const runs: any[] = [
  {
    text: 'Senior React engineer in Canada, 5+ years, under $130k',
    filters: { ...E, skills: ['React'], countries: ['Canada'], minYears: 5, maxSalary: 130000 },
    keywords: [], searchText: 'Senior React engineer', seniority: 'senior',
    relaxable: ['countries', 'maxSalary', 'minYears', 'skills'],
  },
  {
    text: 'Rust developer with AI/ML experience, 5+ years',
    filters: { ...E, skills: ['Rust'], minYears: 5 },
    keywords: ['ai', 'ml'], searchText: 'Rust developer AI/ML', seniority: null,
    relaxable: ['minYears', 'skills'],
  },
];
(async () => {
  for (const r of runs) {
    const query = { filters: r.filters, keywords: r.keywords, searchText: r.searchText, seniority: r.seniority, source: 'rules' as const };
    const t = performance.now();
    const res = await searchCandidates(r.filters, { query, queryText: r.text, relaxable: r.relaxable });
    const ms = Math.round(performance.now() - t);
    console.log(`\n### ${r.text}  (${ms} ms) total=${res.total}`);
    console.log('relaxed:', JSON.stringify(res.relaxed));
    console.log('effective filters:', JSON.stringify(res.filters));
    for (const x of res.results.slice(0, 5)) {
